WITH employees_by_department AS (SELECT dept_id, ROUND(STDDEV(salary), 2) AS stddev_salary, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(job_title))) AS job_title_values FROM employees GROUP BY dept_id) SELECT departments.location, employees_by_department.stddev_salary, employees_by_department.job_title_values FROM departments INNER JOIN employees_by_department ON departments.id = employees_by_department.dept_id WHERE employees_by_department.stddev_salary >= 50 ORDER BY location ASC, job_title_values ASC;
